// Malar Teacher – our own speech API + web server. Everything runs on this machine: no outside AI service, no keys.
//   GET  /api/health  -> { tts: true|false, voices: [...] }
//   POST /api/speak   -> { text, voice, speed }  returns audio (base64 WAV) + word and viseme timings for lip-sync
//   POST /api/prepare -> { texts, voice, speed, start }  generates a whole lesson's speech once, so it later plays without waiting
// Speech is generated by the open-source HeadTTS/Kokoro engine started below, and cached on disk so repeats are instant.
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import crypto from 'node:crypto';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const ROOT = path.dirname(fileURLToPath(import.meta.url));
const PORT = Number(process.env.PORT || 8080), TTS_PORT = Number(process.env.TTS_PORT || 8882);
const PUB = path.join(ROOT, 'public'), CACHE = path.join(ROOT, 'cache'), VOICEDIR = path.join(ROOT, 'voices');
const HT = path.join(ROOT, 'node_modules', '@met4citizen', 'headtts');
const VOICES = ['af_heart', 'af_bella', 'af_nicole', 'bf_emma', 'bf_isabella', 'hf_alpha', 'hf_beta', 'am_michael', 'am_fenrir', 'bm_george', 'bm_lewis', 'hm_omega', 'hm_psi'];
const VOICE_URL = 'https://huggingface.co/onnx-community/Kokoro-82M-v1.0-ONNX/resolve/main/voices/';
const fwd = p => p.split(path.sep).join('/');
for (const d of [CACHE, VOICEDIR, path.join(ROOT, 'node_modules', '@huggingface', 'transformers', '.cache')]) fs.mkdirSync(d, { recursive: true });
const logFile = fs.createWriteStream(path.join(ROOT, 'server.log'), { flags: 'w' });
const log = (...a) => { const s = `[${new Date().toISOString().slice(11, 19)}] ${a.join(' ')}`; console.log(s); logFile.write(s + '\n'); };

let ttsReady = false, tts = null, have = [];
// Engine setting. Measured on the laptop (13 Nov 2026): cpu / fp32 is the fastest; 'webgpu' (graphics chip) and the lighter 'q8' model were both much slower.
// So cpu / fp32 is the default. TTS_DEVICE / TTS_DTYPE can still override it for a different machine.
const PROFILES = [[process.env.TTS_DEVICE || 'cpu', process.env.TTS_DTYPE || 'fp32']];
let prof = 0, DTYPE = PROFILES[0][1];
const hasVoice = v => { try { return fs.statSync(path.join(VOICEDIR, v + '.bin')).size > 1000; } catch { return false; } };

async function fetchVoices() {
  for (const v of VOICES) {
    if (hasVoice(v)) continue;
    try {
      const r = await fetch(VOICE_URL + v + '.bin');
      if (!r.ok) throw new Error('HTTP ' + r.status);
      fs.writeFileSync(path.join(VOICEDIR, v + '.bin'), Buffer.from(await r.arrayBuffer()));
      log('Voice downloaded:', v);
    } catch (e) { log('Voice download failed:', v, e.message); }
  }
  have = VOICES.filter(hasVoice);
}

function startTTS() {
  if (!fs.existsSync(HT)) { log('Voice engine is not installed (node_modules missing). Run "Start Malar Teacher.bat".'); return; }
  if (!have.length) { log('No voices available, the voice engine was not started.'); return; }
  const cfg = path.join(ROOT, 'headtts.config.json');
  fs.writeFileSync(cfg, JSON.stringify({
    server: { port: TTS_PORT, websocket: false, rest: true, corsOrigin: null },
    tts: { threads: Math.max(1, Math.min(Number(process.env.TTS_THREADS || 4), os.cpus().length)), device: PROFILES[prof][0], dtype: PROFILES[prof][1], languages: ['en-us'],
      dictionaryPath: fwd(path.join(HT, 'dictionaries')), voicePath: fwd(VOICEDIR), voices: have.slice(0, 1),
      defaults: { voice: have[0], language: 'en-us', speed: 1, audioEncoding: 'wav' } },
    trace: 0 }, null, 1));
  log('Starting the voice engine. The first start downloads the voice model (about 330 MB), please wait...');
  tts = spawn(process.execPath, [path.join(HT, 'modules', 'headtts-node.mjs'), '--config', cfg], { cwd: HT, stdio: ['ignore', 'pipe', 'pipe'] }); // cwd must be the engine's own folder: it loads its worker file relative to it
  tts.stdout.on('data', d => log('[tts]', String(d).trim()));
  tts.stderr.on('data', d => { const m = String(d).trim(); log('[tts!]', m);
    if (/Loading models failed/.test(m) && prof < PROFILES.length - 1 && !ttsReady) { prof++; log('That engine setting could not be loaded. Trying: ' + PROFILES[prof].join(' / ')); try { tts.kill(); } catch {} setTimeout(startTTS, 1500); } });
  tts.on('exit', c => { ttsReady = false; log('Voice engine stopped, code', c); });
  waitReady();
}
let tries = 0, polling = false;
function waitReady() {
  const poll = setInterval(async () => {
    if (ttsReady || polling) return; polling = true;
    try { await synth({ text: 'Hello.', voice: have[0], speed: 1 }); ttsReady = true; clearInterval(poll); log('Voice engine is ready (' + PROFILES[prof].join(' / ') + ').'); } catch (e) { if (++tries % 10 === 0) log('Voice engine not ready yet (' + tries * 3 + 's): ' + e.message); } finally { polling = false; }
  }, 3000);
}

async function synth({ text, voice, speed }) {
  const r = await fetch(`http://127.0.0.1:${TTS_PORT}/v1/synthesize`, { method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ input: text, voice, language: 'en-us', speed, audioEncoding: 'wav' }) });
  const j = await r.json();
  if (!r.ok || j.error || !j.audio) throw new Error(j.error || 'synthesis failed');
  return j;
}

// Speech jobs: urgent sentences (being spoken now) jump ahead of background prefetch (the next minute of the lesson).
const jobs = new Map(), hi = [], lo = []; let busy = false;
function enqueue(key, params, high) {
  let j = jobs.get(key);
  if (j) { if (high && !j.started && !j.high) { j.high = true; lo.splice(lo.indexOf(j), 1); hi.push(j); } return j.promise; }
  j = { key, params, high, started: false };
  j.promise = new Promise((res, rej) => { j.res = res; j.rej = rej; }); j.promise.catch(() => {});
  jobs.set(key, j); (high ? hi : lo).push(j); pump(); return j.promise;
}
async function pump() {
  if (busy) return; const j = hi.shift() || lo.shift(); if (!j) return;
  busy = true; j.started = true; const t0 = Date.now();
  try { const data = Buffer.from(JSON.stringify(await synth(j.params))); fs.writeFileSync(path.join(CACHE, j.key + '.json'), data);
    log(`speak ${j.high ? 'now ' : 'next'} ${j.params.voice} ${Date.now() - t0}ms "${j.params.text.slice(0, 40)}"`); j.res(data); }
  catch (e) { j.rej(e); } finally { jobs.delete(j.key); busy = false; pump(); }
}
// one place decides how a request is cleaned up and which cache file it maps to (used by /api/speak and /api/prepare)
const norm = b => ({ text: String(b.text || '').trim().slice(0, 480), voice: have.includes(b.voice) ? b.voice : have[0], speed: Math.min(1.5, Math.max(0.6, Number(b.speed) || 1)) });
const keyOf = p => crypto.createHash('sha1').update([p.voice, p.speed.toFixed(2), p.text].join('|')).digest('hex');
async function speak(body) {
  const p = norm(body);
  if (!p.text) throw new Error('empty text');
  const key = keyOf(p);
  const file = path.join(CACHE, key + '.json');
  if (fs.existsSync(file) && !jobs.has(key)) return { hit: true, data: fs.readFileSync(file) };
  if (!ttsReady) throw new Error('voice engine not ready');
  return { hit: false, data: await enqueue(key, p, body.priority !== 'low') };
}

// PREPARE A LESSON: the page sends every sentence a lesson can speak (for one voice and speed). Sentences not yet on disk are
// generated once, in the background, and kept in cache/. After that the whole lesson plays from disk with no waiting.
//   POST /api/prepare { texts:[...], voice, speed, start:true|false, cancel:true|false }
//   -> { total, ready, missing, queued, busy, failed, engine }   (call again with start:false to watch progress)
let prepFailed = 0;
function prepare(body) {
  const seen = new Set(), items = [];
  for (const t of Array.isArray(body.texts) ? body.texts.slice(0, 5000) : []) {
    const p = norm({ text: t, voice: body.voice, speed: body.speed }); if (!p.text) continue;
    const key = keyOf(p); if (seen.has(key)) continue; seen.add(key); items.push({ key, p });
  }
  if (body.cancel) { for (const j of lo.splice(0)) { jobs.delete(j.key); j.rej(new Error('cancelled')); } log('prepare: cancelled'); }
  const missing = items.filter(i => !fs.existsSync(path.join(CACHE, i.key + '.json')));
  if (body.start && missing.length) {
    if (!ttsReady) throw new Error('voice engine not ready');
    prepFailed = 0; let left = missing.length; const t0 = Date.now();
    log(`prepare: ${items.length} sentences, ${missing.length} to generate (${missing[0].p.voice}, speed ${missing[0].p.speed})`);
    for (const i of missing) enqueue(i.key, i.p, false).then(() => {}, e => { if (e.message !== 'cancelled') prepFailed++; }).finally(() => { if (--left === 0) log(`prepare: finished in ${Math.round((Date.now() - t0) / 1000)} s, ${prepFailed} failed`); });
  }
  return { total: items.length, ready: items.length - missing.length, missing: missing.length, queued: hi.length + lo.length, busy, failed: prepFailed, engine: ttsReady };
}

// Online lookup for doubts that are not in the lesson notes: plain encyclopedia search (Simple English Wikipedia first). No AI.
const STOPQ = new Set('a an the is are was were what whats why how when where which who whom does do did can could will would i you me my we it its of in on at to for and or but that this tell about please mam madam miss sir teacher explain mean meaning means called know want'.split(' '));
async function lookup(q) {
  const words = String(q).toLowerCase().replace(/[^a-z0-9\s-]/g, ' ').split(/\s+/).filter(w => w && !STOPQ.has(w)).slice(0, 6);
  if (!words.length) return null;
  const file = path.join(CACHE, 'wiki_' + crypto.createHash('sha1').update(words.join(' ')).digest('hex') + '.json');
  if (fs.existsSync(file)) return JSON.parse(fs.readFileSync(file));
  const H = { headers: { 'User-Agent': 'MalarTeacher/0.3 (free school lessons; local test)' } };
  for (const site of ['simple.wikipedia.org', 'en.wikipedia.org']) {
    try {
      const sr = await (await fetch(`https://${site}/w/api.php?action=query&list=search&srlimit=1&format=json&srsearch=${encodeURIComponent(words.join(' '))}`, H)).json();
      const hit = sr?.query?.search?.[0]; if (!hit) continue;
      const sm = await (await fetch(`https://${site}/api/rest_v1/page/summary/${encodeURIComponent(hit.title.replace(/ /g, '_'))}`, H)).json();
      if (!sm.extract || sm.type === 'disambiguation') continue;
      const sents = sm.extract.replace(/\s*\([^)]*\)/g, '').match(/[^.!?]+[.!?]+/g) || [sm.extract];
      let ex = ''; for (const x of sents) { if ((ex + x).length > 330) break; ex += x; }
      const out = { title: sm.title, extract: (ex || sents[0]).trim(), url: sm.content_urls?.desktop?.page || `https://${site}/wiki/${encodeURIComponent(hit.title)}`, source: site };
      fs.writeFileSync(file, JSON.stringify(out)); log('lookup', site, '->', out.title); return out;
    } catch (e) { log('lookup failed', site, e.message); }
  }
  return null;
}

const MIME = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript', '.mjs': 'text/javascript', '.css': 'text/css', '.json': 'application/json', '.glb': 'model/gltf-binary', '.png': 'image/png', '.jpg': 'image/jpeg', '.svg': 'image/svg+xml' };
http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://x');
    if (url.pathname === '/api/health') { res.writeHead(200, { 'Content-Type': 'application/json' }); return res.end(JSON.stringify({ tts: ttsReady, voices: have })); }
    if (url.pathname === '/api/lookup') { const r = await lookup(url.searchParams.get('q') || ''); res.writeHead(r ? 200 : 404, { 'Content-Type': 'application/json' }); return res.end(JSON.stringify(r || { error: 'nothing found' })); }
    if (url.pathname === '/api/speak' && req.method === 'POST') {
      let raw = ''; for await (const c of req) { raw += c; if (raw.length > 4000) throw new Error('too long'); }
      try { const out = await speak(JSON.parse(raw || '{}')); res.writeHead(200, { 'Content-Type': 'application/json', 'X-Cache': out.hit ? 'hit' : 'miss' }); return res.end(out.data); }
      catch (e) { res.writeHead(503, { 'Content-Type': 'application/json' }); return res.end(JSON.stringify({ error: e.message })); }
    }
    if (url.pathname === '/api/prepare' && req.method === 'POST') {
      let raw = ''; for await (const c of req) { raw += c; if (raw.length > 2e6) throw new Error('too long'); }
      try { const out = prepare(JSON.parse(raw || '{}')); res.writeHead(200, { 'Content-Type': 'application/json' }); return res.end(JSON.stringify(out)); }
      catch (e) { res.writeHead(503, { 'Content-Type': 'application/json' }); return res.end(JSON.stringify({ error: e.message })); }
    }
    let p = path.normalize(path.join(PUB, decodeURIComponent(url.pathname)));
    if (!p.startsWith(PUB)) { res.writeHead(403); return res.end(); }
    if (fs.existsSync(p) && fs.statSync(p).isDirectory()) p = path.join(p, 'index.html');
    if (!fs.existsSync(p)) { res.writeHead(404); return res.end('Not found'); }
    res.writeHead(200, { 'Content-Type': MIME[path.extname(p).toLowerCase()] || 'application/octet-stream', 'Cache-Control': 'no-cache' });
    fs.createReadStream(p).pipe(res);
  } catch (e) { res.writeHead(500); res.end(String(e.message)); }
}).on('error', e => { log(e.code === 'EADDRINUSE' ? 'Malar Teacher is already running in another window. Close that window first, then start again.' : 'Server error: ' + e.message); process.exit(1); }).listen(PORT, '127.0.0.1', () => {
  log(`Malar Teacher is running: http://localhost:${PORT}  (keep this window open; close it to stop)`);
  if (process.platform === 'win32' && !process.env.NO_OPEN) spawn('cmd', ['/c', 'start', '', `http://localhost:${PORT}`], { stdio: 'ignore', detached: true });
});
process.on('exit', () => { try { tts && tts.kill(); } catch {} });
process.on('SIGINT', () => process.exit());
// NO_TTS=1: do not start the engine here, use one already running on TTS_PORT (for testing or a separate speech server)
if (!process.env.NO_TTS) fetchVoices().then(startTTS); else { have = VOICES.slice(); waitReady(); }
